import * as fs from 'fs';
import * as path from 'path';

interface FileAnalysis {
  filename: string;
  fileSize: number;
  entryCount: number;
  patientName: string;
  patientBirthDate: string;
  patientGender: string;
  patientCity: string;
  resourceCounts: Record<string, number>;
  dateRange: {
    earliest: string;
    latest: string;
  };
}

async function analyzeFile(filePath: string): Promise<FileAnalysis> {
  try {
    const content = fs.readFileSync(filePath, 'utf8');
    const data = JSON.parse(content);

    const filename = path.basename(filePath);
    const fileSize = fs.statSync(filePath).size;
    const entryCount = data.entry.length;

    // Get patient info (first entry should be Patient)
    const patient = data.entry[0].resource;
    const patientName = `${patient.name[0].given.join(' ')} ${patient.name[0].family}`;
    const patientBirthDate = patient.birthDate;
    const patientGender = patient.gender;
    const patientCity = patient.address[0].city;

    // Count resource types
    const resourceCounts: Record<string, number> = {};
    data.entry.forEach((entry: any) => {
      const resourceType = entry.resource.resourceType;
      resourceCounts[resourceType] = (resourceCounts[resourceType] || 0) + 1;
    });

    // Find date range
    const dates: string[] = [];
    data.entry.forEach((entry: any) => {
      const resource = entry.resource;
      if (resource.effectiveDateTime) {
        dates.push(resource.effectiveDateTime);
      }
      if (resource.period?.start) {
        dates.push(resource.period.start);
      }
    });

    dates.sort();
    const dateRange = {
      earliest: dates[0] || 'N/A',
      latest: dates[dates.length - 1] || 'N/A'
    };

    return {
      filename,
      fileSize,
      entryCount,
      patientName,
      patientBirthDate,
      patientGender,
      patientCity,
      resourceCounts,
      dateRange
    };
  } catch (error) {
    console.error(`Error analyzing ${filePath}:`, error);
    throw error;
  }
}

async function main() {
  const dataDir = '/Users/hrishioa/Dropbox/Projects/Southbridge/experiments/sealed-agents/tests/healthcare-ehr-langton/data/fhir';

  // Get all JSON files
  const files = fs.readdirSync(dataDir)
    .filter(f => f.endsWith('.json'))
    .map(f => path.join(dataDir, f));

  console.log(`Found ${files.length} JSON files`);

  // Analyze a sample of files (first 10 and last 10 by size)
  const fileSizes = files.map(f => ({
    path: f,
    size: fs.statSync(f).size
  })).sort((a, b) => b.size - a.size);

  const samplesToAnalyze = [
    ...fileSizes.slice(0, 5), // 5 largest
    ...fileSizes.slice(-5)    // 5 smallest
  ];

  console.log('Analyzing sample files...');
  const analyses: FileAnalysis[] = [];

  for (const file of samplesToAnalyze) {
    try {
      console.log(`Analyzing ${path.basename(file.path)} (${(file.size / 1024 / 1024).toFixed(1)}MB)`);
      const analysis = await analyzeFile(file.path);
      analyses.push(analysis);
    } catch (error) {
      console.error(`Failed to analyze ${file.path}`);
    }
  }

  // Print summary
  console.log('\n=== ANALYSIS SUMMARY ===');
  console.log('File Size Distribution:');
  analyses.forEach(a => {
    console.log(`${a.filename}: ${(a.fileSize / 1024 / 1024).toFixed(1)}MB, ${a.entryCount} entries`);
  });

  console.log('\nResource Type Patterns:');
  const allResourceTypes = new Set<string>();
  analyses.forEach(a => Object.keys(a.resourceCounts).forEach(type => allResourceTypes.add(type)));

  Array.from(allResourceTypes).sort().forEach(resourceType => {
    const counts = analyses.map(a => a.resourceCounts[resourceType] || 0);
    const min = Math.min(...counts);
    const max = Math.max(...counts);
    const avg = counts.reduce((a, b) => a + b, 0) / counts.length;
    console.log(`${resourceType}: min=${min}, max=${max}, avg=${avg.toFixed(1)}`);
  });

  console.log('\nPatient Demographics:');
  analyses.forEach(a => {
    console.log(`${a.patientName} (${a.patientGender}, born ${a.patientBirthDate}) - ${a.patientCity}`);
  });
}

main().catch(console.error);
